if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_cert_name() {
    local dir="${argc_config_dir:-/etc/letsencrypt}"
    local path
    for path in "$dir"/live/*/; do
        [[ -d "$path" ]] || continue
        path=${path%/}
        printf '%s\n' "${path##*/}"
    done
}

_choice_plugin() {
    certbot plugins 2>/dev/null | sed -n 's/^\* \([^ ]*\).*/\1/p'
}

_choice_preferred_challenges() {
    printf '%s\n' http dns http-01 dns-01
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
